import type { EngineInterface, ModelUsage, Register, Timer } from 'claude-code'

import type { CacheTtl, CacheTtlOption, StopReason, WarmerConfig, WarmerState } from '../types'

const TTL_MS: Record<CacheTtl, number> = { '1h': 60 * 60_000, '5m': 5 * 60_000 }

// The cache clock starts when a request starts, but the mod only sees the turn end.
// The lead covers the last request's generation time plus one tick.
const PING_LEAD_MS: Record<CacheTtl, number> = { '1h': 5 * 60_000, '5m': 90_000 }

// Prices as multiples of the model's base input price, from
// https://platform.claude.com/docs/en/about-claude/pricing (2026-10-15).
const CACHE_WRITE_RATE: Record<CacheTtl, number> = { '1h': 2, '5m': 1.25 }
// Claude Code caches a fork at the 5m TTL.
const FORK_WRITE_RATE = 1.25
const OUTPUT_RATE = 5
const READ_RATE_BY_MODEL_PREFIX: readonly (readonly [string, number])[] = [
  ['claude-fable-5-1', 0.025],
  ['claude-mythos-5-1', 0.025],
  ['claude-opus-5-5', 0.05],
  ['claude-sonnet-5-5', 0.05],
]
// Haiku 5.5 and older models. An unknown model gets it too, which stops warming early, not late.
const DEFAULT_READ_RATE = 0.1

// A ping this close to expiry may land after it and pay a full rewrite.
const TOO_LATE_MS = 15_000
const TICK_MS = 15_000
const PING_PROMPT = 'Reply with one dot.'

const CACHE_TTL_OPTIONS: readonly CacheTtlOption[] = ['auto', '1h', '5m']

export function parseConfig(options: Readonly<Record<string, unknown>>): WarmerConfig {
  const cacheTtl = options.cacheTtl ?? 'auto'
  if (!CACHE_TTL_OPTIONS.includes(cacheTtl as CacheTtlOption)) {
    throw new Error(`cache-warmer: cacheTtl is ${String(cacheTtl)}; valid options are ${CACHE_TTL_OPTIONS.join(', ')}`)
  }
  const maxPings = Number(options.maxPings ?? 0)
  const minContextTokens = Number(options.minContextTokens ?? 20_000)
  if (!Number.isInteger(maxPings) || maxPings < 0) {
    throw new Error(`cache-warmer: maxPings is ${String(options.maxPings)}; use a whole number, 0 for the break-even count`)
  }
  if (!Number.isFinite(minContextTokens) || minContextTokens < 0) {
    throw new Error(`cache-warmer: minContextTokens is ${String(options.minContextTokens)}; use a token count of 0 or more`)
  }
  return { cacheTtl: cacheTtl as CacheTtlOption, maxPings, minContextTokens }
}

export function parseTtl(text: string | undefined): CacheTtl | null {
  const trimmed = text?.trim().toLowerCase()
  if (trimmed === '1h' || trimmed === '5m') {
    return trimmed
  }
  return null
}

export function readRateFor(model: string): number {
  return READ_RATE_BY_MODEL_PREFIX.find(([prefix]) => model.startsWith(prefix))?.[1] ?? DEFAULT_READ_RATE
}

// In input-token equivalents: what letting the cache lapse costs over keeping it warm.
export function rewriteCost(state: WarmerState): number {
  return state.contextTokens * (CACHE_WRITE_RATE[state.ttl] - state.readRate)
}

export function pingCost(usage: ModelUsage, readRate: number): number {
  return (
    usage.cache_read_input_tokens * readRate +
    usage.cache_creation_input_tokens * FORK_WRITE_RATE +
    usage.input_tokens +
    usage.output_tokens * OUTPUT_RATE
  )
}

// Pinging past the rewrite cost loses even if the person comes back, so the spend
// never exceeds one rewrite: at worst twice the cost of a perfect guess.
function isBudgetSpent(state: WarmerState, config: WarmerConfig): boolean {
  if (config.maxPings > 0) {
    return state.pingCount >= config.maxPings
  }
  const nextPingCost = state.contextTokens * state.readRate
  return state.pingSpendInputTokens + nextPingCost > rewriteCost(state)
}

// A cold cache rewrites the transcript, so it writes more than it reads.
export function isColdPing(usage: ModelUsage): boolean {
  return usage.cache_creation_input_tokens > usage.cache_read_input_tokens
}

export type NextAction = { kind: 'wait' } | { kind: 'ping' } | { kind: 'stop'; reason: StopReason }

// Decided on the clock alone, so a cache that already lapsed (a laptop asleep past expiry)
// costs nothing to detect.
export function nextAction(state: WarmerState, config: WarmerConfig, nowMs: number): NextAction {
  if (!state.isEnabled || state.stopReason !== null || state.isTurnRunning || state.isPinging) {
    return { kind: 'wait' }
  }
  if (state.lastCacheTouchMs === null) {
    return { kind: 'wait' }
  }
  const expiresAtMs = state.lastCacheTouchMs + TTL_MS[state.ttl]
  if (nowMs >= expiresAtMs - TOO_LATE_MS) {
    return { kind: 'stop', reason: 'expired-before-ping' }
  }
  if (nowMs < expiresAtMs - PING_LEAD_MS[state.ttl]) {
    return { kind: 'wait' }
  }
  if (state.contextTokens < config.minContextTokens) {
    return { kind: 'stop', reason: 'small-context' }
  }
  if (isBudgetSpent(state, config)) {
    return { kind: 'stop', reason: 'budget-spent' }
  }
  return { kind: 'ping' }
}

export function describeStop(reason: StopReason): string {
  switch (reason) {
    case 'budget-spent':
      return 'pings cost as much as one cache rewrite'
    case 'expired-before-ping':
      return 'cache expired before a ping could run'
    case 'cold-ping':
      return 'a ping found the cache cold'
    case 'small-context':
      return 'context too small to be worth warming'
    case 'nothing-to-fork':
      return 'nothing to fork yet'
    case 'api-error':
      return 'a ping hit an API error'
    case 'empty-reply':
      return 'a ping got an empty reply'
    case 'aborted':
      return 'a ping was aborted'
    case 'turned-off':
      return 'turned off'
  }
}

export function statusText(state: WarmerState, nowMs: number): string | undefined {
  if (state.stopReason !== null) {
    return `cache warmer stopped: ${describeStop(state.stopReason)}`
  }
  if (!state.isEnabled || state.lastCacheTouchMs === null) {
    return undefined
  }
  const minutesLeft = Math.max(0, Math.round((state.lastCacheTouchMs + TTL_MS[state.ttl] - nowMs) / 60_000))
  const budget = rewriteCost(state)
  const spentPercent = budget > 0 ? Math.round((state.pingSpendInputTokens / budget) * 100) : 0
  return `cache warm ${minutesLeft}m (${state.ttl}) · ${state.pingCount} pings, ${spentPercent}% of a rewrite`
}

async function resolveTtl($: EngineInterface, option: CacheTtlOption): Promise<CacheTtl> {
  switch (option) {
    case '1h':
    case '5m':
      return option
    case 'auto':
      return detectTtl($)
  }
}

// Mirrors Claude Code's own precedence for the main thread's TTL.
async function detectTtl($: EngineInterface): Promise<CacheTtl> {
  if (await $.env.get('FORCE_PROMPT_CACHING_5M')) {
    return '5m'
  }
  const envTtl = parseTtl(await $.env.get('CLAUDE_CODE_PROMPT_CACHE_TTL'))
  if (envTtl !== null) {
    return envTtl
  }
  const settings = await $.settings.read()
  const settingsTtl = parseTtl(typeof settings.promptCacheTtl === 'string' ? settings.promptCacheTtl : undefined)
  if (settingsTtl !== null) {
    return settingsTtl
  }
  const identity = await $.session.identity()
  if (identity.kind === 'claude.ai') {
    // Past plan usage the session runs on usage credits, which get 5m.
    const { rateLimits } = await $.session.usage()
    return rateLimits.some((limit) => limit.percentUsed >= 100) ? '5m' : '1h'
  }
  if (await $.env.get('ENABLE_PROMPT_CACHING_1H')) {
    return '1h'
  }
  return '5m'
}

type Warmer = { config: WarmerConfig; state: WarmerState }

async function showStatus($: EngineInterface, warmer: Warmer) {
  const nowMs = await $.clock.now()
  $.ui.status(statusText(warmer.state, nowMs))
}

async function stop($: EngineInterface, warmer: Warmer, reason: StopReason) {
  warmer.state.stopReason = reason
  await $.ui.log(`cache-warmer: ${describeStop(reason)}`)
}

async function ping($: EngineInterface, warmer: Warmer) {
  const { state } = warmer
  state.isPinging = true
  try {
    const pingStartMs = await $.clock.now()
    const fork = await $.model.fork({ prompt: PING_PROMPT })
    if (!fork.isAnswered) {
      await stop($, warmer, fork.reason)
      return
    }
    state.pingSpendInputTokens += pingCost(fork.usage, state.readRate)
    await $.ui.log(
      `cache-warmer: ping ${state.pingCount + 1} read ${fork.usage.cache_read_input_tokens} wrote ${fork.usage.cache_creation_input_tokens} of ${state.contextTokens}`,
    )
    if (isColdPing(fork.usage)) {
      await stop($, warmer, 'cold-ping')
      return
    }
    state.pingCount += 1
    state.lastCacheTouchMs = pingStartMs
  } finally {
    state.isPinging = false
  }
}

async function onTick($: EngineInterface, warmer: Warmer) {
  const nowMs = await $.clock.now()
  const action = nextAction(warmer.state, warmer.config, nowMs)
  switch (action.kind) {
    case 'wait':
      break
    case 'ping':
      await ping($, warmer)
      break
    case 'stop':
      await stop($, warmer, action.reason)
      break
  }
  await showStatus($, warmer)
}

export const register: Register = (on, options) => {
  const config = parseConfig(options)
  const state: WarmerState = {
    isEnabled: true,
    isTurnRunning: false,
    isPinging: false,
    lastCacheTouchMs: null,
    pingCount: 0,
    pingSpendInputTokens: 0,
    contextTokens: 0,
    readRate: DEFAULT_READ_RATE,
    stopReason: null,
    ttl: '5m',
  }
  const warmer: Warmer = { config, state }
  let tick: Timer | null = null

  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'cache-warmer',
      description: 'Shows the prompt cache warmer, or turns it on or off: /cache-warmer [status|on|off]',
    })
    tick?.cancel()
    // A -p run exits after its turn, so there is no idle cache to keep.
    if (!e.isInteractive) {
      return next(e)
    }
    state.ttl = await resolveTtl($, config.cacheTtl)
    tick = $.clock.every(TICK_MS, () => {
      void onTick($, warmer)
    })
    return next(e)
  })

  on('turn.start', async ($, e, next) => {
    if (e.agentId === undefined) {
      state.isTurnRunning = true
    }
    return next(e)
  })

  on('turn.complete', async ($, e, next) => {
    if (e.agentId !== undefined) {
      return next(e)
    }
    state.isTurnRunning = false
    // An aborted or failed turn may have sent no request, so it leaves the old touch time.
    if (e.usage !== undefined) {
      state.lastCacheTouchMs = await $.clock.now()
      state.pingCount = 0
      state.pingSpendInputTokens = 0
      state.readRate = readRateFor(e.usage.model)
      // The turn's usage sums its requests; the session's figure is the last request's window.
      state.contextTokens = (await $.session.usage()).context.tokens ?? 0
      state.ttl = await resolveTtl($, config.cacheTtl)
      if (state.stopReason !== 'turned-off') {
        state.stopReason = null
      }
    }
    await showStatus($, warmer)
    return next(e)
  })

  on('command.run', { command: 'cache-warmer' }, async ($, e) => {
    const verb = e.args.trim() || 'status'
    if (verb === 'on') {
      state.isEnabled = true
      state.stopReason = null
    } else if (verb === 'off') {
      state.isEnabled = false
      state.stopReason = 'turned-off'
    } else if (verb !== 'status') {
      return { text: `Unknown argument "${verb}". Valid arguments: status, on, off.` }
    }
    await showStatus($, warmer)
    const nowMs = await $.clock.now()
    return { text: statusText(state, nowMs) ?? `cache warmer on (${state.ttl}); waiting for the first turn` }
  })
}

