{
  "name": "cache-warmer",
  "version": "0.1.0",
  "description": "Keeps the prompt cache warm while a Claude Code session is idle, so coming back does not pay a full cache rewrite",
  "author": {
    "name": "Akaike Technologies"
  },
  "license": "MIT",
  "keywords": [
    "prompt-caching",
    "cost",
    "mod"
  ],
  "userConfig": {
    "cacheTtl": {
      "type": "string",
      "title": "Cache TTL",
      "description": "auto reads env, settings and the login kind; 1h or 5m forces it",
      "options": [
        "auto",
        "1h",
        "5m"
      ],
      "default": "auto"
    },
    "maxPings": {
      "type": "number",
      "title": "Pings per idle stretch",
      "description": "0 stops once pings cost as much as one cache rewrite",
      "default": 0
    },
    "minContextTokens": {
      "type": "number",
      "title": "Smallest context worth warming",
      "description": "Below this a cold rewrite costs less than the bookkeeping",
      "default": 20000
    }
  }
}
